#!/usr/bin/env sh
# Generates the Homebrew cask for Brainstorm (to stdout) from a release version + the .dmg's
# checksum. The release workflow uses this to push a bump to fredoliveira/homebrew-tap on every
# tagged release; it also works by hand:
#
#   generate.sh <version> <sha256-dmg>
#
# <version> is bare (0.1.0), not the tag (v0.1.0).
set -eu

if [ $# -ne 2 ]; then
  echo "usage: generate.sh <version> <sha256-dmg>" >&2
  exit 64
fi
version="$1"
sha_dmg="$2"

cat <<CASK
# Homebrew Cask for Brainstorm, the MTG Arena companion.
#
# GENERATED by packaging/homebrew/generate.sh in fredoliveira/brainstorm - the release
# workflow pushes a bump here on every tagged release. Edit the generator, not this file.
#
# Users install with:
#
#     brew install --cask fredoliveira/tap/brainstorm
#
# The app is signed with a Developer ID and notarized by Apple (release.yml).
cask "brainstorm" do
  version "${version}"
  sha256 "${sha_dmg}"

  url "https://github.com/fredoliveira/brainstorm/releases/download/v#{version}/Brainstorm.dmg"
  name "Brainstorm"
  desc "MTG Arena companion: draft ratings, library tracker, 17Lands uploads"
  homepage "https://github.com/fredoliveira/brainstorm"

  depends_on arch: :arm64
  depends_on :macos

  app "Brainstorm.app"

  uninstall quit: "com.helloform.brainstorm"

  zap trash: [
    "~/Library/Application Support/brainstorm",
    "~/Library/Caches/brainstorm",
  ]
end
CASK
